import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.DDY-poMm.js";const p=JSON.parse('{"title":"RWA-BTX 是什么","description":"","frontmatter":{},"headers":[],"relativePath":"zh/intro/what-is.md","filePath":"zh/intro/what-is.md","lastUpdated":1790683574000}'),i={name:"zh/intro/what-is.md"};function n(h,a,l,s,d,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="rwa-btx-是什么" tabindex="-1">RWA-BTX 是什么 <a class="header-anchor" href="#rwa-btx-是什么" aria-label="Permalink to &quot;RWA-BTX 是什么&quot;">​</a></h1><p>RWA-BTX 是一套<strong>中心化数字资产交易平台</strong>，面向希望自主运营交易业务的团队。系统交付即包含运营后台、做市商端、用户 PC 端、用户移动端 H5 与<strong>原生双端 App（Android / iOS）</strong>，覆盖从用户注册、实名、入金、交易、理财到出金的完整链路。</p><h2 id="适合什么场景" tabindex="-1">适合什么场景 <a class="header-anchor" href="#适合什么场景" aria-label="Permalink to &quot;适合什么场景&quot;">​</a></h2><ul><li><strong>自主运营的数字资产交易平台</strong>：需要完整的用户体系、资金体系、交易体系与后台管控</li><li><strong>多品类交易场景</strong>：除数字资产外，还需要提供外汇、商品、股票、指数等传统金融标的行情与交易</li><li><strong>需要精细运营的场景</strong>：菜单、首页币种、玩法开关、VIP 等级等大量运营元素需要在后台随时调整，而不是每次都找技术改代码</li></ul><h2 id="核心特点" tabindex="-1">核心特点 <a class="header-anchor" href="#核心特点" aria-label="Permalink to &quot;核心特点&quot;">​</a></h2><h3 id="一、运营配置驱动界面" tabindex="-1">一、运营配置驱动界面 <a class="header-anchor" href="#一、运营配置驱动界面" aria-label="Permalink to &quot;一、运营配置驱动界面&quot;">​</a></h3><p>用户端的底部菜单、首页金刚区、首页币种、资产页 Tab、侧边栏菜单、VIP 等级门槛、玩法开关等，<strong>全部由运营后台配置下发</strong>。运营调整后用户端即时生效，无需重新发布版本。</p><p>详见<a href="/CoinExchange/zh/guide/site-config">站点配置</a>。</p><h3 id="二、资金动作全程留痕" tabindex="-1">二、资金动作全程留痕 <a class="header-anchor" href="#二、资金动作全程留痕" aria-label="Permalink to &quot;二、资金动作全程留痕&quot;">​</a></h3><p>余额的每一次变动都配套一条资金流水记录，记录变动前后的余额。充值、提现、划转、下单、结算、后台调账等所有资金动作均为原子化事务处理，避免高并发下出现余额异常或重复入账。</p><h3 id="三、双入金通道容灾" tabindex="-1">三、双入金通道容灾 <a class="header-anchor" href="#三、双入金通道容灾" aria-label="Permalink to &quot;三、双入金通道容灾&quot;">​</a></h3><p>平台支持两套数字资产入金通道并行，运营可在后台一键切换。单一通道异常时可即时切换，业务不中断。用户拥有稳定的专属充值地址，反复充值无需重新获取；充值以链上实际到账金额为准自动入账，无需人工审核介入。</p><h3 id="四、极端行情下的确定性" tabindex="-1">四、极端行情下的确定性 <a class="header-anchor" href="#四、极端行情下的确定性" aria-label="Permalink to &quot;四、极端行情下的确定性&quot;">​</a></h3><p>系统对合约清算与结算引入了报价新鲜度校验：行情链路中断时，残留的陈旧报价会被识别并拒绝采信，系统主动暂停该标的的清算与条件单触发，待行情恢复后按真实市价重新判定。</p><blockquote><p><strong>原则明确：清算延迟可以接受，错误清算不可接受。</strong></p></blockquote><p>同一笔仓位只会被结算一次；期权类订单到期时若行情暂时缺失，采用&quot;有限等待 + 超时兜底&quot;策略，超时则撤单并原路退还本金并留痕，不会出现&quot;扣了钱既不结算也不退款&quot;的悬挂订单。</p><h2 id="不适合什么" tabindex="-1">不适合什么 <a class="header-anchor" href="#不适合什么" aria-label="Permalink to &quot;不适合什么&quot;">​</a></h2><ul><li><strong>去中心化交易（DEX）场景</strong>：本系统是中心化撮合与记账模型，链上仅用于充值入金与提现出金</li><li><strong>需要接入真实交易所订单簿深度的场景</strong>：系统的成交价取自平台行情缓存</li></ul><h2 id="申请测试站体验" tabindex="-1">申请测试站体验 <a class="header-anchor" href="#申请测试站体验" aria-label="Permalink to &quot;申请测试站体验&quot;">​</a></h2><p>测试站地址与体验账号不在文档中公开，申请方式见 <a href="/CoinExchange/zh/contact/">联系我们</a>。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>想快速了解系统有哪些功能 → <a href="/CoinExchange/zh/intro/features">能力总览</a></li><li>想知道系统由哪几部分组成、分别谁用 → <a href="/CoinExchange/zh/intro/components">系统组成</a></li><li>运营人员上手 → <a href="/CoinExchange/zh/guide/admin-login">后台登录与权限</a></li><li>想亲手试一试 → <a href="/CoinExchange/zh/contact/">联系我们</a> 申请测试站体验账号</li></ul>',22)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
